        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_Generate">MIX_Generate</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer(CSDL.Audio.AudioSpec)">AudioSpec)</see></seealso>
        public static extern void Generate();

        /// <summary>
        /// <para>Report the name of a specific audio decoders.</para>
        /// </summary>
        /// <remarks>
        /// <para>An audio decoder is what turns specific audio file formats into usable PCM data. For example, there might be an MP3 decoder, or a WAV decoder, etc. SDL_mixer probably has several decoders built in.</para>
        /// <para>The names are capital English letters and numbers, low-ASCII. They don't necessarily map to a specific file format; Some decoders, like "XMP" operate on multiple file types, and more than one decoder might handle the same file type, like "DRMP3" vs "MPG123". Note that in that last example, neither decoder is called "MP3".</para>
        /// <para>The index of a specific decoder is decided during <c>MIX_Init</c> and does not change until the library is deinitialized. Valid indices are between zero and the return value of <see cref="CSDL.Mixer.AudioDecoder.Count">Count</see>.</para>
        /// <para>The returned pointer is const memory owned by SDL_mixer; do not free it.</para>
        /// </remarks>
        /// <param name="index">the index of the decoder to query.</param>
        /// <returns>
        /// <para>(const char *) Returns a UTF-8 (really, ASCII) string of the decoder's name, or NULL if <c>index</c> is invalid.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetAudioDecoder">MIX_GetAudioDecoder</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.AudioDecoder.Count">Count</see></seealso>
        public static extern void GetAudioDecoder();

        /// <summary>
        /// <para>Query the initial audio format of a <c>MIX_AudioDecoder</c>.</para>
        /// </summary>
        /// <remarks>
        /// <para>Note that some audio files can change format in the middle; some explicitly support this, but a more common example is two MP3 files concatenated together. In many cases, SDL_mixer will correctly handle these sort of files, but this function will only report the initial format a file uses.</para>
        /// </remarks>
        /// <param name="audiodecoder">the audio decoder to query.</param>
        /// <param name="spec">on success, audio format details will be stored here.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetAudioDecoderFormat">MIX_GetAudioDecoderFormat</seealso></SDLWiki>
        public static extern void GetAudioDecoderFormat();

