        /// <para>Get the properties associated with a <c>MIX_AudioDecoder</c>.</para>
        /// </summary>
        /// <remarks>
        /// <para>SDL_mixer offers some properties of its own, but this can also be a convenient place to store app-specific data.</para>
        /// <para>A SDL_PropertiesID is created the first time this function is called for a given <c>MIX_AudioDecoder</c>, if necessary.</para>
        /// <para>The file-specific metadata exposed through this function is identical to those available through <see cref="CSDL.Mixer.Audio.Properties">Properties</see>. Please refer to that function's documentation for details.</para>
        /// </remarks>
        /// <param name="audiodecoder">the audio decoder to query.</param>
        /// <returns>
        /// <para>(SDL_PropertiesID) Returns a valid property ID on success or 0 on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetAudioDecoderProperties">MIX_GetAudioDecoderProperties</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Audio.Properties">Properties</see></seealso>
        public static extern void GetAudioDecoderProperties();

        /// <summary>
        /// <para>Get the length of a <c>MIX_Audio</c>'s playback in sample frames.</para>
        /// </summary>
        /// <remarks>
        /// <para>This information is also available via the <see cref="CSDL.Mixer.Props.MetadataDurationFramesNumber">MetadataDurationFramesNumber</see> property, but it's common enough to provide a simple accessor function.</para>
        /// <para>This reports the length of the data in _sample frames_, so sample-perfect mixing can be possible. Sample frames are only meaningful as a measure of time if the sample rate (frequency) is also known. To convert from sample frames to milliseconds, use <see cref="CSDL.Mixer.Audio.FramesToMS">FramesToMS</see>.</para>
        /// <para>Not all audio file formats can report the complete length of the data they will produce through decoding: some can't calculate it, some might produce infinite audio.</para>
        /// <para>Also, some file formats can only report duration as a unit of time, which means SDL_mixer might have to estimate sample frames from that information. With less precision, the reported duration might be off by a few sample frames in either direction.</para>
        /// <para>This will return a value >= 0 if a duration is known. It might also return <see cref="DurationUnknown"/> or <see cref="DurationInfinite"/>.</para>
        /// </remarks>
        /// <param name="audio">the audio to query.</param>
        /// <returns>
        /// <para>(Sint64) Returns the length of the audio in sample frames, or <see cref="DurationUnknown"/> or <see cref="DurationInfinite"/>.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetAudioDuration">MIX_GetAudioDuration</seealso></SDLWiki>
        public static extern void GetAudioDuration();

        /// <summary>
        /// <para>Query the initial audio format of a <c>MIX_Audio</c>.</para>
        /// </summary>
        /// <remarks>
        /// <para>Note that some audio files can change format in the middle; some explicitly support this, but a more common example is two MP3 files concatenated together. In many cases, SDL_mixer will correctly handle these sort of files, but this function will only report the initial format a file uses.</para>
        /// </remarks>
        /// <param name="audio">the audio to query.</param>
        /// <param name="spec">on success, audio format details will be stored here.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetAudioFormat">MIX_GetAudioFormat</seealso></SDLWiki>
        public static extern void GetAudioFormat();

        /// <summary>
        /// <para>Get the properties associated with a <c>MIX_Audio</c>.</para>
        /// </summary>
        /// <remarks>
        /// <para>SDL_mixer offers some properties of its own, but this can also be a convenient place to store app-specific data.</para>
        /// <para>A SDL_PropertiesID is created the first time this function is called for a given <c>MIX_Audio</c>, if necessary.</para>
        /// <para>The following read-only properties are provided by SDL_mixer:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataTitleString">MetadataTitleString</see>: the audio's title ("Smells Like Teen Spirit").</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataArtistString">MetadataArtistString</see>: the audio's artist name ("Nirvana").</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataAlbumString">MetadataAlbumString</see>: the audio's album name ("Nevermind").</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataCopyrightString">MetadataCopyrightString</see>: the audio's copyright info ("Copyright (c) 1991")</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataTrackNumber">MetadataTrackNumber</see>: the audio's track number on the album (1)</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataTotalTracksNumber">MetadataTotalTracksNumber</see>: the total tracks on the album (13)</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataYearNumber">MetadataYearNumber</see>: the year the audio was released (1991)</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataDurationFramesNumber">MetadataDurationFramesNumber</see>: The sample frames worth of PCM data that comprise this audio. It might be off by a little if the decoder only knows the duration as a unit of time.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.MetadataDurationInfiniteBoolean">MetadataDurationInfiniteBoolean</see>: if true, audio never runs out of sound to generate. This isn't necessarily always known to SDL_mixer, though.</description></item>
        /// </list>
        /// <para>Other properties, documented with <see cref="CSDL.Mixer.Audio.Load">Load</see>, may also be present.</para>
        /// <para>Note that the metadata properties are whatever SDL_mixer finds in things like ID3 tags, and they often have very little standardized formatting, may be missing, and can be completely wrong if the original data is untrustworthy (like an MP3 from a P2P file sharing service).</para>
        /// </remarks>
        /// <param name="audio">the audio to query.</param>
        /// <returns>
        /// <para>(SDL_PropertiesID) Returns a valid property ID on success or 0 on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetAudioProperties">MIX_GetAudioProperties</seealso></SDLWiki>
        public static extern void GetAudioProperties();

