        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetGroupMixer">MIX_GetGroupMixer</seealso></SDLWiki>
        public static extern void GetGroupMixer();

