        /// </summary>
        /// <remarks>
        /// <para>This returns the number of loops still pending; if a track will eventually complete and loop to play again one more time, this will return 1. If a track _was_ looping but is on its final iteration of the loop (will stop when this iteration completes), this will return zero.</para>
        /// <para>A track that is looping infinitely will return -1. This value does not report an error in this case.</para>
        /// <para>A track that is stopped (not playing and not paused) will have zero loops remaining.</para>
        /// <para>On various errors (<c>MIX_Init</c> was not called, the track is NULL), this returns zero, but there is no mechanism to distinguish errors from non-looping tracks.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <returns>
        /// <para>(int) Returns the number of pending loops, zero if not looping, and -1 if looping infinitely.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetTrackLoops">MIX_GetTrackLoops</seealso></SDLWiki>
        public static extern void GetTrackLoops();

        /// <summary>
        /// <para>Get the <c>MIX_Mixer</c> that owns a <c>MIX_Track</c>.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is the mixer pointer that was passed to <see cref="CSDL.Mixer.Mixer.CreateTrack">CreateTrack</see>.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <returns>
        /// <para>(<c>MIX_Mixer</c> *) Returns the mixer associated with the track, or NULL on error; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetTrackMixer">MIX_GetTrackMixer</seealso></SDLWiki>
        public static extern void GetTrackMixer();

        /// <summary>
        /// <para>Get the current input position of a playing track.</para>
        /// </summary>
        /// <remarks>
        /// <para>(Not to be confused with <see cref="CSDL.Mixer.Track.Get3DPosition">Get3DPosition</see>, which is positioning of the track in 3D space, not the playback position of its audio data.)</para>
        /// <para>Position is defined in _sample frames_ of decoded audio, not units of time, so that sample-perfect mixing can be achieved. To instead operate in units of time, use <see cref="CSDL.Mixer.Track.FramesToMS">FramesToMS</see> to convert the return value to milliseconds.</para>
        /// <para>Stopped and paused tracks will report the position when they halted. Playing tracks will report the current position, which will change over time.</para>
        /// </remarks>
        /// <param name="track">the track to change.</param>
        /// <returns>
        /// <para>(Sint64) Returns the track's current sample frame position, or -1 on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetTrackPlaybackPosition">MIX_GetTrackPlaybackPosition</seealso></SDLWiki>
        /// <seealso><c>MIX_SetTrackPlaybackPosition</c></seealso>
        public static extern void GetTrackPlaybackPosition();

        /// <summary>
        /// <para>Get the properties associated with a track.</para>
        /// </summary>
        /// <remarks>
        /// <para>Currently SDL_mixer assigns no properties of its own to a track, but this can be a convenient place to store app-specific data.</para>
        /// <para>A SDL_PropertiesID is created the first time this function is called for a given track.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <returns>
        /// <para>(SDL_PropertiesID) Returns a valid property ID on success or 0 on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetTrackProperties">MIX_GetTrackProperties</seealso></SDLWiki>
        public static extern void GetTrackProperties();

        /// <summary>
        /// <para>Return the number of sample frames remaining to be mixed in a track.</para>
        /// </summary>
        /// <remarks>
        /// <para>If the track is playing or paused, and its total duration is known, this will report how much audio is left to mix. If the track is playing, future calls to this function will report different values.</para>
        /// <para>Remaining audio is defined in _sample frames_ of decoded audio, not units of time, so that sample-perfect mixing can be achieved. To instead operate in units of time, use <see cref="CSDL.Mixer.Track.FramesToMS">FramesToMS</see> to convert the return value to milliseconds.</para>
        /// <para>This function does not take into account fade-outs or looping, just the current mixing position vs the duration of the track.</para>
        /// <para>If the duration of the track isn't known, or <c>track</c> is NULL, this function returns -1. A stopped track reports 0.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <returns>
        /// <para>(Sint64) Returns the total sample frames still to be mixed, or -1 if unknown.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetTrackRemaining">MIX_GetTrackRemaining</seealso></SDLWiki>
        public static extern void GetTrackRemaining();

        /// <summary>
        /// <para>Get the tags currently associated with a track.</para>
        /// </summary>
        /// <remarks>
        /// <para>Tags are not provided in any guaranteed order.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <param name="count">a pointer filled in with the number of tags returned, can be NULL.</param>
        /// <returns>
        /// <para>(char **) Returns an array of the tags, NULL-terminated, or NULL on failure; call SDL_GetError() for more information. This is a single allocation that should be freed with SDL_free() when it is no longer needed.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_GetTrackTags">MIX_GetTrackTags</seealso></SDLWiki>
        public static extern void GetTrackTags();

        /// <summary>
        /// <para>Initialize the SDL_mixer library.</para>
        /// </summary>
        /// <remarks>
        /// <para>This must be successfully called once before (almost) any other SDL_mixer function can be used.</para>
        /// <para>It is safe to call this multiple times; the library will only initialize once, and won't deinitialize until <see cref="CSDL.Mixer.Mixer.Quit">Quit</see> has been called a matching number of times. Extra attempts to init report success.</para>
        /// </remarks>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>This function is not thread safe.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_Init">MIX_Init</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer.Quit">Quit</see></seealso>
        public static extern void Init();

        /// <summary>
        /// <para>Load audio for playback from a file.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is equivalent to calling:</para>
        /// <code language="c">
        /// MIX_LoadAudio_IO(mixer, SDL_IOFromFile(path, "rb"), predecode, true);
        /// </code>
        /// <para>This function loads data from a path on the filesystem. There is also a version that loads from an SDL_IOStream (<see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see>), and one that accepts properties for ultimate control (<see cref="CSDL.Mixer.Audio.Load">Load</see>).</para>
        /// </remarks>
        /// <param name="mixer">a mixer this audio is intended to be used with. May be NULL.</param>
        /// <param name="path">the path on the filesystem to load data from.</param>
        /// <param name="predecode">if true, data will be fully uncompressed before returning.</param>
        /// <returns>
        /// <para>(<c>MIX_Audio</c> *) Returns an audio object that can be used to make sound on a mixer, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_LoadAudio">MIX_LoadAudio</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.Load">Load</see></seealso>
        public static extern void LoadAudio();

        /// <summary>
        /// <para>Load audio for playback from an SDL_IOStream.</para>
        /// </summary>
        /// <remarks>
        /// <para>In normal usage, apps should load audio once, maybe at startup, then play it multiple times.</para>
        /// <para>When loading audio, it will be cached fully in RAM in its original data format. Each time it plays, the data will be decoded. For example, an MP3 will be stored in memory in MP3 format and be decompressed on the fly during playback. This is a tradeoff between i/o overhead and memory usage.</para>
        /// <para>If <c>predecode</c> is true, the data will be decompressed during load and stored as raw PCM data. This might dramatically increase loading time and memory usage, but there will be no need to decompress data during playback.</para>
        /// <para>(One could also use <see cref="CSDL.Mixer.Track.SetIOStream">SetIOStream</see> to bypass loading the data into RAM upfront at all, but this offers still different tradeoffs. The correct approach depends on the app's needs and employing different approaches in different situations can make sense.)</para>
        /// <para><c>MIX_Audio</c> objects can be shared between mixers. This function takes a <c>MIX_Mixer</c>, to imply this is the most likely place it will be used and loading should try to match its audio format, but the resulting audio can be used elsewhere. If <c>mixer</c> is NULL, SDL_mixer will set reasonable defaults.</para>
        /// <para>Once a <c>MIX_Audio</c> is created, it can be assigned to a <c>MIX_Track</c> with <see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see>, or played without any management with <see cref="CSDL.Mixer.Mixer.Play">Play</see>.</para>
        /// <para>When done with a <c>MIX_Audio</c>, it can be freed with <see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see>.</para>
        /// <para>This function loads data from an SDL_IOStream. There is also a version that loads from a path on the filesystem (<see cref="CSDL.Mixer.Audio(Mixer,string,bool)">Audio(Mixer,string,bool)</see>), and one that accepts properties for ultimate control (<see cref="CSDL.Mixer.Audio.Load">Load</see>).</para>
        /// <para>The SDL_IOStream provided must be able to seek, or loading will fail. If the stream can't seek (data is coming from an HTTP connection, etc), consider caching the data to memory or disk first and creating a new stream to read from there.</para>
        /// </remarks>
        /// <param name="mixer">a mixer this audio is intended to be used with. May be NULL.</param>
        /// <param name="io">the SDL_IOStream to load data from.</param>
        /// <param name="predecode">if true, data will be fully uncompressed before returning.</param>
        /// <param name="closeio">true if SDL_mixer should close <c>io</c> before returning (success or failure).</param>
        /// <returns>
        /// <para>(<c>MIX_Audio</c> *) Returns an audio object that can be used to make sound on a mixer, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_LoadAudio_IO">MIX_LoadAudio_IO</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer,string,bool)">Audio(Mixer,string,bool)</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.Load">Load</see></seealso>
        public static extern void LoadAudio_IO();

        /// <summary>
        /// <para>Load audio for playback from a memory buffer without making a copy.</para>
        /// </summary>
        /// <remarks>
        /// <para>When loading audio through most other LoadAudio functions, the data will be cached fully in RAM in its original data format, for decoding on-demand. This function does most of the same work as those functions, but instead uses a buffer of memory provided by the app that it does not make a copy of.</para>
        /// <para>This buffer must live for the entire time the returned <c>MIX_Audio</c> lives, as the mixer will access the buffer whenever it needs to mix more data.</para>
        /// <para>This function is meant to maximize efficiency: if the data is already in memory and can remain there, don't copy it. This data can be in any supported audio file format (WAV, MP3, etc); it will be decoded on the fly while mixing. Unlike <see cref="CSDL.Mixer.Audio(Mixer,string,bool)">Audio(Mixer,string,bool)</see>, there is no <c>predecode</c> option offered here, as this is meant to optimize for data that's already in memory and intends to exist there for significant time; since predecoding would only need the file format data once, upfront, one could simply wrap it in SDL_CreateIOFromConstMem() and pass that to <see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see>.</para>
        /// <para><c>MIX_Audio</c> objects can be shared between multiple mixers. The <c>mixer</c> parameter just suggests the most likely mixer to use this audio, in case some optimization might be applied, but this is not required, and a NULL mixer may be specified.</para>
        /// <para>If <c>free_when_done</c> is true, SDL_mixer will call <c>SDL_free(data)</c> when the returned <c>MIX_Audio</c> is eventually destroyed. This can be useful when the data is not static, but rather loaded elsewhere for this specific <c>MIX_Audio</c> and simply wants to avoid the extra copy.</para>
        /// <para>As audio format information is obtained from the file format metadata, this isn't useful for raw PCM data; in that case, use <see cref="CSDL.Mixer.Audio.LoadRawNoCopy">LoadRawNoCopy</see> instead, which offers an SDL_AudioSpec.</para>
        /// <para>Once a <c>MIX_Audio</c> is created, it can be assigned to a <c>MIX_Track</c> with <see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see>, or played without any management with <see cref="CSDL.Mixer.Mixer.Play">Play</see>.</para>
        /// <para>When done with a <c>MIX_Audio</c>, it can be freed with <see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see>.</para>
        /// </remarks>
        /// <param name="mixer">a mixer this audio is intended to be used with. May be NULL.</param>
        /// <param name="data">the buffer where the audio data lives.</param>
        /// <param name="datalen">the size, in bytes, of the buffer.</param>
        /// <param name="free_when_done">if true, <c>data</c> will be given to SDL_free() when the <c>MIX_Audio</c> is destroyed.</param>
        /// <returns>
        /// <para>(<c>MIX_Audio</c> *) Returns an audio object that can be used to make sound on a mixer, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_LoadAudioNoCopy">MIX_LoadAudioNoCopy</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.LoadRawNoCopy">LoadRawNoCopy</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see></seealso>
        public static extern void LoadAudioNoCopy();

        /// <summary>
        /// <para>Load audio for playback through a collection of properties.</para>
        /// </summary>
        /// <remarks>
        /// <para>Please see <see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see> for a description of what the various LoadAudio functions do. This function uses properties to dictate how it operates, and exposes functionality the other functions don't provide.</para>
        /// <para>SDL_PropertiesID are discussed in <a href="https://wiki.libsdl.org/SDL3/CategoryProperties">SDL's documentation</a> . These are the supported properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Mixer.Props.AudioLoadIostreamPointer">AudioLoadIostreamPointer</see>: a pointer to an SDL_IOStream to be used to load audio data. Required. This stream must be able to seek!</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.AudioLoadCloseioBoolean">AudioLoadCloseioBoolean</see>: true if SDL_mixer should close the SDL_IOStream before returning (success or failure).</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.AudioLoadPredecodeBoolean">AudioLoadPredecodeBoolean</see>: true if SDL_mixer should fully decode and decompress the data before returning. Otherwise it will be stored in its original state and decompressed on demand.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.AudioLoadPreferredMixerPointer">AudioLoadPreferredMixerPointer</see>: a pointer to a <c>MIX_Mixer</c>, in case steps can be made to match its format when decoding. Optional.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.AudioLoadSkipMetadataTagsBoolean">AudioLoadSkipMetadataTagsBoolean</see>: true to skip parsing metadata tags, like ID3 and APE tags. This can be used to speed up loading _if the data definitely doesn't have these tags_. Some decoders will fail if these tags are present when this property is true.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.AudioLoadIgnoreLoopsBoolean">AudioLoadIgnoreLoopsBoolean</see>: true to ignore metadata in the audio data specifying loop points. This will make a file decode from start to finish without looping, even if the file specified it should have. This audio can still be looped at playback time via <c>MIX_Track</c> loop settings, regardless of this setting. Default false.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.AudioDecoderString">AudioDecoderString</see>: the name of the decoder to use for this data. Optional. If not specified, SDL_mixer will examine the data and choose the best decoder. These names are the same returned from <see cref="CSDL.Mixer.AudioDecoder.GetName">GetName</see>.</description></item>
        /// </list>
        /// <para>Specific decoders might accept additional custom properties, such as where to find soundfonts for MIDI playback, etc.</para>
        /// </remarks>
        /// <param name="props">a set of properties on how to load audio.</param>
        /// <returns>
        /// <para>(<c>MIX_Audio</c> *) Returns an audio object that can be used to make sound on a mixer, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_LoadAudioWithProperties">MIX_LoadAudioWithProperties</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer,string,bool)">Audio(Mixer,string,bool)</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see></seealso>
        public static extern void LoadAudioWithProperties();

        /// <summary>
        /// <para>Load raw PCM data from a memory buffer.</para>
        /// </summary>
        /// <remarks>
        /// <para>There are other options for _streaming_ raw PCM: an SDL_AudioStream can be connected to a track, as can an SDL_IOStream, and will read from those sources on-demand when it is time to mix the audio. This function is useful for loading static audio data that is meant to be played multiple times.</para>
        /// <para>This function will load the raw data in its entirety and cache it in RAM, allocating a copy. If the original data will outlive the created <c>MIX_Audio</c>, you can use <see cref="CSDL.Mixer.Audio.LoadRawNoCopy">LoadRawNoCopy</see> to avoid extra allocations and copies.</para>
        /// <para><c>MIX_Audio</c> objects can be shared between multiple mixers. The <c>mixer</c> parameter just suggests the most likely mixer to use this audio, in case some optimization might be applied, but this is not required, and a NULL mixer may be specified.</para>
        /// </remarks>
        /// <param name="mixer">a mixer this audio is intended to be used with. May be NULL.</param>
        /// <param name="data">the raw PCM data to load.</param>
        /// <param name="datalen">the size, in bytes, of the raw PCM data.</param>
        /// <param name="spec">what format the raw data is in.</param>
        /// <returns>
        /// <para>(<c>MIX_Audio</c> *) Returns an audio object that can be used to make sound on a mixer, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_LoadRawAudio">MIX_LoadRawAudio</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.LoadRaw">LoadRaw</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.LoadRawNoCopy">LoadRawNoCopy</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see></seealso>
        public static extern void LoadRawAudio();

        /// <summary>
        /// <para>Load raw PCM data from an SDL_IOStream.</para>
        /// </summary>
        /// <remarks>
        /// <para>There are other options for _streaming_ raw PCM: an SDL_AudioStream can be connected to a track, as can an SDL_IOStream, and will read from those sources on-demand when it is time to mix the audio. This function is useful for loading static audio data that is meant to be played multiple times.</para>
        /// <para>This function will load the raw data in its entirety and cache it in RAM.</para>
        /// <para><c>MIX_Audio</c> objects can be shared between multiple mixers. The <c>mixer</c> parameter just suggests the most likely mixer to use this audio, in case some optimization might be applied, but this is not required, and a NULL mixer may be specified.</para>
        /// </remarks>
        /// <param name="mixer">a mixer this audio is intended to be used with. May be NULL.</param>
        /// <param name="io">the SDL_IOStream to load data from.</param>
        /// <param name="spec">what format the raw data is in.</param>
        /// <param name="closeio">true if SDL_mixer should close <c>io</c> before returning (success or failure).</param>
        /// <returns>
        /// <para>(<c>MIX_Audio</c> *) Returns an audio object that can be used to make sound on a mixer, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_LoadRawAudio_IO">MIX_LoadRawAudio_IO</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.LoadRaw">LoadRaw</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.LoadRawNoCopy">LoadRawNoCopy</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see></seealso>
        public static extern void LoadRawAudio_IO();

        /// <summary>
        /// <para>Load raw PCM data from a memory buffer without making a copy.</para>
        /// </summary>
        /// <remarks>
        /// <para>This buffer must live for the entire time the returned <c>MIX_Audio</c> lives, as the mixer will access the buffer whenever it needs to mix more data.</para>
        /// <para>This function is meant to maximize efficiency: if the data is already in memory and can remain there, don't copy it. But it can also lead to some interesting tricks, like changing the buffer's contents to alter multiple playing tracks at once. (But, of course, be careful when being too clever.)</para>
        /// <para><c>MIX_Audio</c> objects can be shared between multiple mixers. The <c>mixer</c> parameter just suggests the most likely mixer to use this audio, in case some optimization might be applied, but this is not required, and a NULL mixer may be specified.</para>
        /// <para>If <c>free_when_done</c> is true, SDL_mixer will call <c>SDL_free(data)</c> when the returned <c>MIX_Audio</c> is eventually destroyed. This can be useful when the data is not static, but rather composed dynamically for this specific <c>MIX_Audio</c> and simply wants to avoid the extra copy.</para>
        /// </remarks>
        /// <param name="mixer">a mixer this audio is intended to be used with. May be NULL.</param>
        /// <param name="data">the buffer where the raw PCM data lives.</param>
        /// <param name="datalen">the size, in bytes, of the buffer.</param>
        /// <param name="spec">what format the raw data is in.</param>
        /// <param name="free_when_done">if true, <c>data</c> will be given to SDL_free() when the <c>MIX_Audio</c> is destroyed.</param>
        /// <returns>
        /// <para>(<c>MIX_Audio</c> *) Returns an audio object that can be used to make sound on a mixer, or NULL on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_LoadRawAudioNoCopy">MIX_LoadRawAudioNoCopy</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.LoadRaw">LoadRaw</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio.LoadRaw">LoadRaw</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer?,File.IOStream,bool,bool)">IOStream,bool,bool)</see></seealso>
        public static extern void LoadRawAudioNoCopy();

        /// <summary>
        /// <para>Lock a mixer by obtaining its internal mutex.</para>
        /// </summary>
        /// <remarks>
        /// <para>While locked, the mixer will not be able to mix more audio or change its internal state in another thread. Those other threads will block until the mixer is unlocked again.</para>
        /// <para>Under the hood, this function calls SDL_LockMutex(), so all the same rules apply: the lock can be recursive, it must be unlocked the same number of times from the same thread that locked it, etc.</para>
        /// <para>Just about every SDL_mixer API _also_ locks the mixer while doing its work, as does the SDL audio device thread while actual mixing is in progress, so basic use of this library never requires the app to explicitly lock the device to be thread safe. There are two scenarios where this can be useful, however:</para>
        /// <list type="bullet">
        /// <item><description>The app has a provided a callback that the mixing thread might call, and there is some app state that needs to be protected against race conditions as changes are made and mixing progresses simultaneously. Any lock can be used for this, but this is a conveniently-available lock.</description></item>
        /// <item><description>The app wants to make multiple, atomic changes to the mix. For example, to start several tracks at the exact same moment, one would lock the mixer, call <see cref="CSDL.Mixer.Track.Play">Play</see> multiple times, and then unlock again; all the tracks will start mixing on the same sample frame.</description></item>
        /// </list>
        /// <para>Each call to this function must be paired with a call to <see cref="CSDL.Mixer.Mixer.Unlock">Unlock</see> from the same thread. It is safe to lock a mixer multiple times; it remains locked until the final matching unlock call.</para>
        /// <para>Do not lock the mixer for significant amounts of time, or it can cause audio dropouts. Just do simple things quickly and unlock again.</para>
        /// <para>Locking a NULL mixer is a safe no-op.</para>
        /// </remarks>
        /// <param name="mixer">the mixer to lock. May be NULL.</param>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_LockMixer">MIX_LockMixer</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer.Unlock">Unlock</see></seealso>
        public static extern void LockMixer();

        /// <summary>
        /// <para>Convert milliseconds to sample frames at a specific sample rate.</para>
        /// </summary>
        /// <remarks>
        /// <para>If <c>sample_rate</c> is &lt;= 0, this returns -1. If <c>ms</c> is &lt; 0, this returns -1.</para>
        /// </remarks>
        /// <param name="sample_rate">the sample rate to use for conversion.</param>
        /// <param name="ms">the milliseconds to convert to rate-specific sample frames.</param>
        /// <returns>
        /// <para>(Sint64) Returns Converted number of sample frames, or -1 for errors; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_MSToFrames">MIX_MSToFrames</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer.FramesToMS">FramesToMS</see></seealso>
        public static extern void MSToFrames();

        /// <summary>
        /// <para>Pause all currently-playing tracks.</para>
        /// </summary>
        /// <remarks>
        /// <para>A paused track is not considered "stopped," so its <c>MIX_TrackStoppedCallback</c> will not fire if paused, but it won't change state by default, generate audio, or generally make progress, until it is resumed.</para>
        /// <para>This function makes all tracks on the specified mixer that are currently playing move to a paused state. They can later be resumed.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to pause all tracks.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_PauseAllTracks">MIX_PauseAllTracks</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Resume">Resume</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Mixer.ResumeAll">ResumeAll</see></seealso>
        public static extern void PauseAllTracks();

        /// <summary>
        /// <para>Pause all tracks with a specific tag.</para>
        /// </summary>
        /// <remarks>
        /// <para>A paused track is not considered "stopped," so its <c>MIX_TrackStoppedCallback</c> will not fire if paused, but it won't change state by default, generate audio, or generally make progress, until it is resumed.</para>
        /// <para>This function makes all currently-playing tracks on the specified mixer, with a specific tag, move to a paused state. They can later be resumed.</para>
        /// <para>Tracks that match the specified tag that aren't currently playing are ignored.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to pause tracks.</param>
        /// <param name="tag">the tag to use when searching for tracks.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_PauseTag">MIX_PauseTag</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Pause">Pause</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Resume">Resume</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Mixer.ResumeTag">ResumeTag</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.AddTag">AddTag</see></seealso>
        public static extern void PauseTag();

        /// <summary>
        /// <para>Pause a currently-playing track.</para>
        /// </summary>
        /// <remarks>
        /// <para>A paused track is not considered "stopped," so its <c>MIX_TrackStoppedCallback</c> will not fire if paused, but it won't change state by default, generate audio, or generally make progress, until it is resumed.</para>
        /// <para>It is legal to pause a track that's in any state (playing, already paused, or stopped). Unless the track is currently playing, pausing does nothing, and returns true. A false return is only used to signal errors here (such as <c>MIX_Init</c> not being called or <c>track</c> being NULL).</para>
        /// </remarks>
        /// <param name="track">the track to pause.</param>
        /// <returns>
        /// <para>(bool) Returns true if the track has paused, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_PauseTrack">MIX_PauseTrack</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Resume">Resume</see></seealso>
        public static extern void PauseTrack();

        /// <summary>
        /// <para>Play a <c>MIX_Audio</c> from start to finish without any management.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is what we term a "fire-and-forget" sound. Internally, SDL_mixer will manage a temporary track to mix the specified <c>MIX_Audio</c>, cleaning it up when complete. No options can be provided for how to do the mixing, like <see cref="CSDL.Mixer.Track.Play">Play</see> offers, and since the track is not available to the caller, no adjustments can be made to mixing over time.</para>
        /// <para>This is not the function to build an entire game of any complexity around, but it can be convenient to play simple, one-off sounds that can't be stopped early. An example would be a voice saying "GAME OVER" during an unpausable endgame sequence.</para>
        /// <para>There are no limits to the number of fire-and-forget sounds that can mix at once (short of running out of memory), and SDL_mixer keeps an internal pool of temporary tracks it creates as needed and reuses when available.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to play this audio.</param>
        /// <param name="audio">the audio input to play.</param>
        /// <returns>
        /// <para>(bool) Returns true if the track has begun mixing, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_PlayAudio">MIX_PlayAudio</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Play">Play</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Audio(Mixer,string,bool)">Audio(Mixer,string,bool)</see></seealso>
        public static extern void PlayAudio();

        /// <summary>
        /// <para>Start (or restart) mixing all tracks with a specific tag for playback.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function follows all the same rules as <see cref="CSDL.Mixer.Track.Play">Play</see>; please refer to its documentation for the details. Unlike that function, <see cref="PlayTag"/> operates on multiple tracks at once that have the specified tag applied, via <see cref="CSDL.Mixer.Track.AddTag">AddTag</see>.</para>
        /// <para>If all of your tagged tracks have different sample rates, it would make sense to use the <c>*_MILLISECONDS_NUMBER</c> properties in your <c>options</c>, instead of <c>*_FRAMES_NUMBER</c>, and let SDL_mixer figure out how to apply it to each track.</para>
        /// <para>This function returns true if all tagged tracks are started (or restarted). If any track fails, this function returns false, but all tracks that could start will still be started even when this function reports failure.</para>
        /// <para>From the point of view of the mixing process, all tracks that successfully (re)start will do so at the exact same moment.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to look for tagged tracks.</param>
        /// <param name="tag">the tag to use when searching for tracks.</param>
        /// <param name="options">the set of options that will be applied to each track.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_PlayTag">MIX_PlayTag</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Play">Play</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.AddTag">AddTag</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Stop">Stop</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Pause">Pause</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.IsPlaying">IsPlaying</see></seealso>
        public static extern void PlayTag();

        /// <summary>
        /// <para>Start (or restart) mixing a track for playback.</para>
        /// </summary>
        /// <remarks>
        /// <para>The track will use whatever input was last assigned to it when playing; an input must be assigned to this track or this function will fail. Inputs are assigned with calls to <see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see>, <see cref="CSDL.Mixer.Track.SetAudioStream">SetAudioStream</see>, or <see cref="CSDL.Mixer.Track.SetIOStream">SetIOStream</see>.</para>
        /// <para>If the track is already playing, or paused, this will restart the track with the newly-specified parameters.</para>
        /// <para>As there are several parameters, and more may be added in the future, they are specified with an SDL_PropertiesID. The parameters have reasonable defaults, and specifying a 0 for <c>options</c> will choose defaults for everything.</para>
        /// <para>SDL_PropertiesID are discussed in <a href="https://wiki.libsdl.org/SDL3/CategoryProperties">SDL's documentation</a> .</para>
        /// <para>These are the supported properties:</para>
        /// <list type="bullet">
        /// <item><description><see cref="CSDL.Mixer.Props.PlayLoopsNumber">PlayLoopsNumber</see>: The number of times to loop the track when it reaches the end. A value of 1 will loop to the start one time. Zero will not loop at all. A value of -1 requests infinite loops. If the input is not seekable and this value isn't zero, this function will report success but the track will stop at the point it should loop. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayMaxFrameNumber">PlayMaxFrameNumber</see>: Mix at most to this sample frame position in the track. This will be treated as if the input reach EOF at this point in the audio file. If -1, mix all available audio without a limit. Default -1.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayMaxMillisecondsNumber">PlayMaxMillisecondsNumber</see>: The same as using the <see cref="CSDL.Mixer.Props.PlayMaxFrameNumber">PlayMaxFrameNumber</see> property, but the value is specified in milliseconds instead of sample frames. If both properties are specified, the sample frames value is favored. Default -1.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayStartFrameNumber">PlayStartFrameNumber</see>: Start mixing from this sample frame position in the track's input. A value &lt;= 0 will begin from the start of the track's input. If the input is not seekable and this value is > 0, this function will report failure. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayStartMillisecondNumber">PlayStartMillisecondNumber</see>: The same as using the <see cref="CSDL.Mixer.Props.PlayStartFrameNumber">PlayStartFrameNumber</see> property, but the value is specified in milliseconds instead of sample frames. If both properties are specified, the sample frames value is favored. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayLoopStartFrameNumber">PlayLoopStartFrameNumber</see>: If the track is looping, this is the sample frame position that the track will loop back to; this lets one play an intro at the start of a track on the first iteration, but have a loop point somewhere in the middle thereafter. A value &lt;= 0 will begin the loop from the start of the track's input. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayLoopStartMillisecondNumber">PlayLoopStartMillisecondNumber</see>: The same as using the <see cref="CSDL.Mixer.Props.PlayLoopStartFrameNumber">PlayLoopStartFrameNumber</see> property, but the value is specified in milliseconds instead of sample frames. If both properties are specified, the sample frames value is favored. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayFadeInFramesNumber">PlayFadeInFramesNumber</see>: The number of sample frames over which to fade in the newly-started track. The track will begin mixing silence and reach full volume smoothly over this many sample frames. If the track loops before the fade-in is complete, it will continue to fade correctly from the loop point. A value &lt;= 0 will disable fade-in, so the track starts mixing at full volume. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayFadeInMillisecondsNumber">PlayFadeInMillisecondsNumber</see>: The same as using the <see cref="CSDL.Mixer.Props.PlayFadeInFramesNumber">PlayFadeInFramesNumber</see> property, but the value is specified in milliseconds instead of sample frames. If both properties are specified, the sample frames value is favored. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayFadeInStartGainFloat">PlayFadeInStartGainFloat</see>: If fading in, start fading from this volume level. 0.0f is silence and 1.0f is full volume, every in between is a linear change in gain. The specified value will be clamped between 0.0f and 1.0f. Default 0.0f.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayAppendSilenceFramesNumber">PlayAppendSilenceFramesNumber</see>: At the end of mixing this track, after all loops are complete, append this many sample frames of silence as if it were part of the audio file. This allows for apps to implement effects in callbacks, like reverb, that need to generate samples past the end of the stream's audio, or perhaps introduce a delay before starting a new sound on the track without having to manage it directly. A value &lt;= 0 generates no silence before stopping the track. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayAppendSilenceMillisecondsNumber">PlayAppendSilenceMillisecondsNumber</see>: The same as using the <see cref="CSDL.Mixer.Props.PlayAppendSilenceFramesNumber">PlayAppendSilenceFramesNumber</see> property, but the value is specified in milliseconds instead of sample frames. If both properties are specified, the sample frames value is favored. Default 0.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayHaltWhenExhaustedBoolean">PlayHaltWhenExhaustedBoolean</see>: If true, when input is completely consumed for the track, the mixer will mark the track as stopped (and call any appropriate <c>MIX_TrackStoppedCallback</c>, etc); to play more, the track will need to be restarted. If false, the track will just not contribute to the mix, but it will not be marked as stopped. There may be clever logic tricks this exposes generally, but this property is specifically useful when the track's input is an SDL_AudioStream assigned via <see cref="CSDL.Mixer.Track.SetAudioStream">SetAudioStream</see>. Setting this property to true can be useful when pushing a complete piece of audio to the stream that has a definite ending, as the track will operate like any other audio was applied. Setting to false means as new data is added to the stream, the mixer will start using it as soon as possible, which is useful when audio should play immediately as it drips in: new VoIP packets, etc. Note that in this situation, if the audio runs out when needed, there _will_ be gaps in the mixed output, so try to buffer enough data to avoid this when possible. Note that a track is not consider exhausted until all its loops and appended silence have been mixed (and also, that loops don't mean anything when the input is an AudioStream). Default true.</description></item>
        /// <item><description><see cref="CSDL.Mixer.Props.PlayStartOrderNumber">PlayStartOrderNumber</see>: This is a special-case property that most apps can ignore. For mod file formats, start mixing from a specific "order" index instead of the start of the file. A value &lt; 0 will cause this property to be ignored. If the decoder doesn't support this property, it will also be ignored. If this property is _not_ ignored, the <see cref="CSDL.Mixer.Props.PlayStartFrameNumber">PlayStartFrameNumber</see> and <see cref="CSDL.Mixer.Props.PlayStartMillisecondNumber">PlayStartMillisecondNumber</see> properties will be ignored instead. Default -1. Since SDL_mixer 3.2.2.</description></item>
        /// </list>
        /// <para>If this function fails, mixing of this track will not start (or restart, if it was already started).</para>
        /// </remarks>
        /// <param name="track">the track to start (or restart) mixing.</param>
        /// <param name="options">a set of properties that control playback. May be zero.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_PlayTrack">MIX_PlayTrack</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer.PlayTag">PlayTag</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Mixer.Play">Play</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Stop">Stop</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Pause">Pause</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.IsPlaying">IsPlaying</see></seealso>
        public static extern void PlayTrack();

        /// <summary>
        /// <para>Deinitialize the SDL_mixer library.</para>
        /// </summary>
        /// <remarks>
        /// <para>This must be called when done with the library, probably at the end of your program.</para>
        /// <para>It is safe to call this multiple times; the library will only deinitialize once, when this function is called the same number of times as <c>MIX_Init</c> was successfully called.</para>
        /// <para>Once you have successfully deinitialized the library, it is safe to call <c>MIX_Init</c> to reinitialize it for further use.</para>
        /// <para>On successful deinitialization, SDL_mixer will destroy almost all created objects, including objects of type:</para>
        /// <list type="bullet">
        /// <item><description><c>MIX_Mixer</c></description></item>
        /// <item><description><c>MIX_Track</c></description></item>
        /// <item><description><c>MIX_Audio</c></description></item>
        /// <item><description><c>MIX_Group</c></description></item>
        /// <item><description><c>MIX_AudioDecoder</c></description></item>
        /// </list>
        /// <para>...which is to say: it's possible a single call to this function will clean up anything it allocated, stop all audio output, close audio devices, etc. Don't attempt to destroy objects after this call. The app is still encouraged to manage their resources carefully and clean up first, treating this function as a safety net against memory leaks.</para>
        /// </remarks>
        /// <threadsafety>This function is not thread safe.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_Quit">MIX_Quit</seealso></SDLWiki>
        /// <seealso><c>MIX_Init</c></seealso>
        public static extern void Quit();

        /// <summary>
        /// <para>Resume all currently-paused tracks.</para>
        /// </summary>
        /// <remarks>
        /// <para>A paused track is not considered "stopped," so its <c>MIX_TrackStoppedCallback</c> will not fire if paused, but it won't change state by default, generate audio, or generally make progress, until it is resumed.</para>
        /// <para>This function makes all tracks on the specified mixer that are currently paused move to a playing state.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to resume all tracks.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_ResumeAllTracks">MIX_ResumeAllTracks</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Pause">Pause</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Mixer.PauseAll">PauseAll</see></seealso>
        public static extern void ResumeAllTracks();

        /// <summary>
        /// <para>Resume all tracks with a specific tag.</para>
        /// </summary>
        /// <remarks>
        /// <para>A paused track is not considered "stopped," so its <c>MIX_TrackStoppedCallback</c> will not fire if paused, but it won't change state by default, generate audio, or generally make progress, until it is resumed.</para>
        /// <para>This function makes all currently-paused tracks on the specified mixer, with a specific tag, move to a playing state.</para>
        /// <para>Tracks that match the specified tag that aren't currently paused are ignored.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to resume tracks.</param>
        /// <param name="tag">the tag to use when searching for tracks.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_ResumeTag">MIX_ResumeTag</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Resume">Resume</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Pause">Pause</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Mixer.PauseTag">PauseTag</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.AddTag">AddTag</see></seealso>
        public static extern void ResumeTag();

        /// <summary>
        /// <para>Resume a currently-paused track.</para>
        /// </summary>
        /// <remarks>
        /// <para>A paused track is not considered "stopped," so its <c>MIX_TrackStoppedCallback</c> will not fire if paused, but it won't change state by default, generate audio, or generally make progress, until it is resumed.</para>
        /// <para>It is legal to resume a track that's in any state (playing, paused, or stopped). Unless the track is currently paused, resuming does nothing, and returns true. A false return is only used to signal errors here (such as <c>MIX_Init</c> not being called or <c>track</c> being NULL).</para>
        /// </remarks>
        /// <param name="track">the track to resume.</param>
        /// <returns>
        /// <para>(bool) Returns true if the track has resumed, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_ResumeTrack">MIX_ResumeTrack</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Pause">Pause</see></seealso>
        public static extern void ResumeTrack();

        /// <summary>
        /// <para>Set a callback that fires when a mixer group has completed mixing.</para>
        /// </summary>
        /// <remarks>
        /// <para>After all playing tracks in a mixer group have pulled in more data from their inputs, transformed it, and mixed together into a single buffer, a callback can be fired. This lets an app view the data at the last moment that it is still a part of this group. It can also change the data in any way it pleases during this callback, and the mixer will continue as if this data came directly from the group's mix buffer.</para>
        /// <para>Each group has its own unique callback. Tracks that aren't in an explicit <c>MIX_Group</c> are mixed in an internal grouping that is not available to the app.</para>
        /// <para>Passing a NULL callback here is legal; it disables this group's callback.</para>
        /// </remarks>
        /// <param name="group">the mixing group to assign this callback to.</param>
        /// <param name="cb">the function to call when the group mixes. May be NULL.</param>
        /// <param name="userdata">an opaque pointer provided to the callback for its own personal use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetGroupPostMixCallback">MIX_SetGroupPostMixCallback</seealso></SDLWiki>
        /// <seealso><c>MIX_GroupMixCallback</c></seealso>
        public static extern void SetGroupPostMixCallback();

        /// <summary>
        /// <para>Set a mixer's master frequency ratio.</para>
        /// </summary>
        /// <remarks>
        /// <para>Each mixer has a master frequency ratio, that affects the entire mix. This can cause the final output to change speed and pitch. A value greater than 1.0f will play the audio faster, and at a higher pitch. A value less than 1.0f will play the audio slower, and at a lower pitch. 1.0f is normal speed.</para>
        /// <para>Each track _also_ has a frequency ratio; it will be applied when mixing that track's audio regardless of the master setting. The master setting affects the final output after all mixing has been completed.</para>
        /// <para>A mixer's master frequency ratio defaults to 1.0f.</para>
        /// <para>This value can be changed at any time to adjust the future mix.</para>
        /// </remarks>
        /// <param name="mixer">the mixer to adjust.</param>
        /// <param name="ratio">the frequency ratio. Must be between 0.01f and 100.0f.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetMixerFrequencyRatio">MIX_SetMixerFrequencyRatio</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer.FrequencyRatio">FrequencyRatio</see></seealso>
        /// <seealso><c>MIX_SetTrackFrequencyRatio</c></seealso>
        public static extern void SetMixerFrequencyRatio();

        /// <summary>
        /// <para>Set a mixer's master gain control.</para>
        /// </summary>
        /// <remarks>
        /// <para>Each mixer has a master gain, to adjust the volume of the entire mix. Each sample passing through the pipeline is modulated by this gain value. A gain of zero will generate silence, 1.0f will not change the mixed volume, and larger than 1.0f will increase the volume. Negative values are illegal. There is no maximum gain specified, but this can quickly get extremely loud, so please be careful with this setting.</para>
        /// <para>A mixer's master gain defaults to 1.0f.</para>
        /// <para>This value can be changed at any time to adjust the future mix.</para>
        /// </remarks>
        /// <param name="mixer">the mixer to adjust.</param>
        /// <param name="gain">the new gain value.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetMixerGain">MIX_SetMixerGain</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer.Gain">Gain</see></seealso>
        /// <seealso><c>MIX_SetTrackGain</c></seealso>
        public static extern void SetMixerGain();

        /// <summary>
        /// <para>Set a callback that fires when all mixing has completed.</para>
        /// </summary>
        /// <remarks>
        /// <para>After all mixer groups have processed, their buffers are mixed together into a single buffer for the final output, at which point a callback can be fired. This lets an app view the data at the last moment before mixing completes. It can also change the data in any way it pleases during this callback, and the mixer will continue as if this data is the final output.</para>
        /// <para>Each mixer has its own unique callback.</para>
        /// <para>Passing a NULL callback here is legal; it disables this mixer's callback.</para>
        /// </remarks>
        /// <param name="mixer">the mixer to assign this callback to.</param>
        /// <param name="cb">the function to call when the mixer mixes. May be NULL.</param>
        /// <param name="userdata">an opaque pointer provided to the callback for its own personal use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetPostMixCallback">MIX_SetPostMixCallback</seealso></SDLWiki>
        /// <seealso><c>MIX_PostMixCallback</c></seealso>
        public static extern void SetPostMixCallback();

        /// <summary>
        /// <para>Set the gain control of all tracks with a specific tag.</para>
        /// </summary>
        /// <remarks>
        /// <para>Each track has its own gain, to adjust its overall volume. Each sample from this track is modulated by this gain value. A gain of zero will generate silence, 1.0f will not change the mixed volume, and larger than 1.0f will increase the volume. Negative values are illegal. There is no maximum gain specified, but this can quickly get extremely loud, so please be careful with this setting.</para>
        /// <para>A track's gain defaults to 1.0f.</para>
        /// <para>This will change the gain control on tracks on the specified mixer that have the specified tag.</para>
        /// <para>From the point of view of the mixing process, all tracks that successfully change gain values will do so at the exact same moment.</para>
        /// <para>This value can be changed at any time to adjust the future mix.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to look for tagged tracks.</param>
        /// <param name="tag">the tag to use when searching for tracks.</param>
        /// <param name="gain">the new gain value.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTagGain">MIX_SetTagGain</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Gain">Gain</see></seealso>
        /// <seealso><c>MIX_SetTrackGain</c></seealso>
        /// <seealso><c>MIX_SetMixerGain</c></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.AddTag">AddTag</see></seealso>
        public static extern void SetTagGain();

        /// <summary>
        /// <para>Set a track's position in 3D space.</para>
        /// </summary>
        /// <remarks>
        /// <para>(Please note that SDL_mixer is not intended to be a extremely powerful 3D API. It lacks 3D features that other APIs like OpenAL offer: there's no doppler effect, distance models, rolloff, etc. This is meant to be Good Enough for games that can use some positional sounds and can even take advantage of surround-sound configurations.)</para>
        /// <para>If <c>position</c> is not NULL, this track will be switched into 3D positional mode. If <c>position</c> is NULL, this will disable positional mixing (both the full 3D spatialization of this function and forced-stereo mode of <see cref="CSDL.Mixer.Track.SetStereo">SetStereo</see>).</para>
        /// <para>In 3D positional mode, SDL_mixer will mix this track as if it were positioned in 3D space, including distance attenuation (quieter as it gets further from the listener) and spatialization (positioned on the correct speakers to suggest direction, either with stereo outputs or full surround sound).</para>
        /// <para>For a mono speaker output, spatialization is effectively disabled but distance attenuation will still work, which is all you can really do with a single speaker.</para>
        /// <para>The coordinate system operates like OpenGL or OpenAL: a "right-handed" coordinate system. See <see cref="CSDL.Mixer.Point3D">Point3D</see> for the details.</para>
        /// <para>The listener is always at coordinate (0,0,0) and can't be changed.</para>
        /// <para>The track's input will be converted to mono (1 channel) so it can be rendered across the correct speakers.</para>
        /// </remarks>
        /// <param name="track">the track for which to set 3D position.</param>
        /// <param name="position">the new 3D position for the track. May be NULL.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrack3DPosition">MIX_SetTrack3DPosition</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Get3DPosition">Get3DPosition</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetStereo">SetStereo</see></seealso>
        public static extern void SetTrack3DPosition();

        /// <summary>
        /// <para>Set a <c>MIX_Track</c>'s input to a <c>MIX_Audio</c>.</para>
        /// </summary>
        /// <remarks>
        /// <para>A <c>MIX_Audio</c> is audio data stored in RAM (possibly still in a compressed form). One <c>MIX_Audio</c> can be assigned to multiple tracks at once.</para>
        /// <para>Once a track has a valid input, it can start mixing sound by calling <see cref="CSDL.Mixer.Track.Play">Play</see>, or possibly <see cref="CSDL.Mixer.Mixer.PlayTag">PlayTag</see>.</para>
        /// <para>Calling this function with a NULL audio input is legal, and removes any input from the track. If the track was currently playing, the next time the mixer runs, it'll notice this and mark the track as stopped, calling any assigned <c>MIX_TrackStoppedCallback</c>.</para>
        /// <para>It is legal to change the input of a track while it's playing, however some states, like loop points, may cease to make sense with the new audio. In such a case, one can call <see cref="CSDL.Mixer.Track.Play">Play</see> again to adjust parameters.</para>
        /// <para>The track will hold a reference to the provided <c>MIX_Audio</c>, so it is safe to call <see cref="CSDL.Mixer.Audio.DisposeResource">DisposeResource</see> on it while the track is still using it. The track will drop its reference (and possibly free the resources) once it is no longer using the <c>MIX_Audio</c>.</para>
        /// </remarks>
        /// <param name="track">the track on which to set a new audio input.</param>
        /// <param name="audio">the new audio input to set. May be NULL.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackAudio">MIX_SetTrackAudio</seealso></SDLWiki>
        public static extern void SetTrackAudio();

        /// <summary>
        /// <para>Set a <c>MIX_Track</c>'s input to an SDL_AudioStream.</para>
        /// </summary>
        /// <remarks>
        /// <para>Using an audio stream allows the application to generate any type of audio, in any format, possibly procedurally or on-demand, and mix in with all other tracks.</para>
        /// <para>When a track uses an audio stream, it will call SDL_GetAudioStreamData as it needs more audio to mix. The app can either buffer data to the stream ahead of time, or set a callback on the stream to provide data as needed. Please refer to SDL's documentation for details.</para>
        /// <para>A given audio stream may only be assigned to a single track at a time; duplicate assignments won't return an error, but assigning a stream to multiple tracks will cause each track to read from the stream arbitrarily, causing confusion and incorrect mixing.</para>
        /// <para>Once a track has a valid input, it can start mixing sound by calling <see cref="CSDL.Mixer.Track.Play">Play</see>, or possibly <see cref="CSDL.Mixer.Mixer.PlayTag">PlayTag</see>.</para>
        /// <para>Calling this function with a NULL audio stream is legal, and removes any input from the track. If the track was currently playing, the next time the mixer runs, it'll notice this and mark the track as stopped, calling any assigned <c>MIX_TrackStoppedCallback</c>.</para>
        /// <para>It is legal to change the input of a track while it's playing, however some states, like loop points, may cease to make sense with the new audio. In such a case, one can call <see cref="CSDL.Mixer.Track.Play">Play</see> again to adjust parameters.</para>
        /// <para>The provided audio stream must remain valid until the track no longer needs it (either by changing the track's input or destroying the track).</para>
        /// </remarks>
        /// <param name="track">the track on which to set a new audio input.</param>
        /// <param name="stream">the audio stream to use as the track's input.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackAudioStream">MIX_SetTrackAudioStream</seealso></SDLWiki>
        public static extern void SetTrackAudioStream();

        /// <summary>
        /// <para>Set a callback that fires when the mixer has transformed a track's audio.</para>
        /// </summary>
        /// <remarks>
        /// <para>As a track needs to mix more data, it pulls from its input (a <c>MIX_Audio</c>, an SDL_AudioStream, etc). This input might be a compressed file format, like MP3, so a little more data is uncompressed from it.</para>
        /// <para>Once the track has PCM data to start operating on, and its raw callback has completed, it will begin to transform the audio: gain, fading, frequency ratio, 3D positioning, etc.</para>
        /// <para>A callback can be fired after all these transformations, but before the transformed data is mixed into other tracks. This lets an app view the data at the last moment that it is still a part of this track. It can also change the data in any way it pleases during this callback, and the mixer will continue as if this data came directly from the input.</para>
        /// <para>Each track has its own unique cooked callback.</para>
        /// <para>Passing a NULL callback here is legal; it disables this track's callback.</para>
        /// </remarks>
        /// <param name="track">the track to assign this callback to.</param>
        /// <param name="cb">the function to call when the track mixes. May be NULL.</param>
        /// <param name="userdata">an opaque pointer provided to the callback for its own personal use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackCookedCallback">MIX_SetTrackCookedCallback</seealso></SDLWiki>
        /// <seealso><c>MIX_TrackMixCallback</c></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetRawCallback">SetRawCallback</see></seealso>
        public static extern void SetTrackCookedCallback();

        /// <summary>
        /// <para>Change the frequency ratio of a track.</para>
        /// </summary>
        /// <remarks>
        /// <para>The frequency ratio is used to adjust the rate at which audio data is consumed. Changing this effectively modifies the speed and pitch of the track's audio. A value greater than 1.0f will play the audio faster, and at a higher pitch. A value less than 1.0f will play the audio slower, and at a lower pitch. 1.0f is normal speed.</para>
        /// <para>The default value is 1.0f.</para>
        /// <para>This value can be changed at any time to adjust the future mix.</para>
        /// </remarks>
        /// <param name="track">the track on which to change the frequency ratio.</param>
        /// <param name="ratio">the frequency ratio. Must be between 0.01f and 100.0f.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackFrequencyRatio">MIX_SetTrackFrequencyRatio</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.FrequencyRatio">FrequencyRatio</see></seealso>
        public static extern void SetTrackFrequencyRatio();

        /// <summary>
        /// <para>Set a track's gain control.</para>
        /// </summary>
        /// <remarks>
        /// <para>Each track has its own gain, to adjust its overall volume. Each sample from this track is modulated by this gain value. A gain of zero will generate silence, 1.0f will not change the mixed volume, and larger than 1.0f will increase the volume. Negative values are illegal. There is no maximum gain specified, but this can quickly get extremely loud, so please be careful with this setting.</para>
        /// <para>A track's gain defaults to 1.0f.</para>
        /// <para>This value can be changed at any time to adjust the future mix.</para>
        /// </remarks>
        /// <param name="track">the track to adjust.</param>
        /// <param name="gain">the new gain value.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackGain">MIX_SetTrackGain</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Gain">Gain</see></seealso>
        /// <seealso><c>MIX_SetMixerGain</c></seealso>
        public static extern void SetTrackGain();

        /// <summary>
        /// <para>Assign a track to a mixing group.</para>
        /// </summary>
        /// <remarks>
        /// <para>All tracks in a group are mixed together, and that output is made available to the app before it is mixed into the final output.</para>
        /// <para>Tracks can only be in one group at a time, and the track and group must have been created on the same <c>MIX_Mixer</c>.</para>
        /// <para>Setting a track to a NULL group will remove it from any app-created groups, and reassign it to the mixer's internal default group.</para>
        /// </remarks>
        /// <param name="track">the track to set mixing group assignment.</param>
        /// <param name="group">the new mixing group to assign to. May be NULL.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackGroup">MIX_SetTrackGroup</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer.CreateGroup">CreateGroup</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Group.SetPostMixCallback">SetPostMixCallback</see></seealso>
        public static extern void SetTrackGroup();

        /// <summary>
        /// <para>Set a <c>MIX_Track</c>'s input to an SDL_IOStream.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is not the recommended way to set a track's input, but this can be useful for a very specific scenario: a large file, to be played once, that must be read from disk in small chunks as needed. In most cases, however, it is preferable to create a <c>MIX_Audio</c> ahead of time and use <see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see> instead.</para>
        /// <para>The stream supplied here should provide an audio file in a supported format. SDL_mixer will parse it during this call to make sure it's valid, and then will read file data from the stream as it needs to decode more during mixing.</para>
        /// <para>The stream must be able to seek through the complete set of data, or this function will fail.</para>
        /// <para>A given IOStream may only be assigned to a single track at a time; duplicate assignments won't return an error, but assigning a stream to multiple tracks will cause each track to read from the stream arbitrarily, causing confusion, incorrect mixing, or failure to decode.</para>
        /// <para>Once a track has a valid input, it can start mixing sound by calling <see cref="CSDL.Mixer.Track.Play">Play</see>, or possibly <see cref="CSDL.Mixer.Mixer.PlayTag">PlayTag</see>.</para>
        /// <para>Calling this function with a NULL stream is legal, and removes any input from the track. If the track was currently playing, the next time the mixer runs, it'll notice this and mark the track as stopped, calling any assigned <c>MIX_TrackStoppedCallback</c>.</para>
        /// <para>It is legal to change the input of a track while it's playing, however some states, like loop points, may cease to make sense with the new audio. In such a case, one can call <see cref="CSDL.Mixer.Track.Play">Play</see> again to adjust parameters.</para>
        /// <para>The provided stream must remain valid until the track no longer needs it (either by changing the track's input or destroying the track).</para>
        /// </remarks>
        /// <param name="track">the track on which to set a new audio input.</param>
        /// <param name="io">the new i/o stream to use as the track's input.</param>
        /// <param name="closeio">if true, close the stream when done with it.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackIOStream">MIX_SetTrackIOStream</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.SetRawIOStream">SetRawIOStream</see></seealso>
        public static extern void SetTrackIOStream();

        /// <summary>
        /// <para>Change the number of times a currently-playing track will loop.</para>
        /// </summary>
        /// <remarks>
        /// <para>This replaces any previously-set remaining loops. A value of 1 will loop to the start of playback one time. Zero will not loop at all. A value of -1 requests infinite loops. If the input is not seekable and <c>num_loops</c> isn't zero, this function will report success but the track will stop at the point it should loop.</para>
        /// <para>The new loop count replaces any previous state, even if the track has already looped.</para>
        /// <para>This has no effect on a track that is stopped, or rather, starting a stopped track later will set a new loop count, replacing this value. Stopped tracks can specify a loop count while starting via <see cref="CSDL.Mixer.Props.PlayLoopsNumber">PlayLoopsNumber</see>. This function is intended to alter that count in the middle of playback.</para>
        /// </remarks>
        /// <param name="track">the track to configure.</param>
        /// <param name="num_loops">new number of times to loop. Zero to disable looping, -1 to loop infinitely.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackLoops">MIX_SetTrackLoops</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Loops">Loops</see></seealso>
        public static extern void SetTrackLoops();

        /// <summary>
        /// <para>Set the current output channel map of a track.</para>
        /// </summary>
        /// <remarks>
        /// <para>Channel maps are optional; most things do not need them, instead passing data in the order that SDL expects.</para>
        /// <para>The output channel map reorders track data after transformations and before it is mixed into a mixer group. This can be useful for reversing stereo channels, for example.</para>
        /// <para>Each item in the array represents an input channel, and its value is the channel that it should be remapped to. To reverse a stereo signal's left and right values, you'd have an array of <c>{ 1, 0 }</c>. It is legal to remap multiple channels to the same thing, so <c>{ 1, 1 }</c> would duplicate the right channel to both channels of a stereo signal. An element in the channel map set to -1 instead of a valid channel will mute that channel, setting it to a silence value.</para>
        /// <para>You cannot change the number of channels through a channel map, just reorder/mute them.</para>
        /// <para>Tracks default to no remapping applied. Passing a NULL channel map is legal, and turns off remapping.</para>
        /// <para>SDL_mixer will copy the channel map; the caller does not have to save this array after this call.</para>
        /// </remarks>
        /// <param name="track">the track to change.</param>
        /// <param name="chmap">the new channel map, NULL to reset to default.</param>
        /// <param name="count">The number of channels in the map.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackOutputChannelMap">MIX_SetTrackOutputChannelMap</seealso></SDLWiki>
        public static extern void SetTrackOutputChannelMap();

        /// <summary>
        /// <para>Seek a playing track to a new position in its input.</para>
        /// </summary>
        /// <remarks>
        /// <para>(Not to be confused with <see cref="CSDL.Mixer.Track.Set3DPosition">Set3DPosition</see>, which is positioning of the track in 3D space, not the playback position of its audio data.)</para>
        /// <para>On a playing track, the next time the mixer runs, it will start mixing from the new position.</para>
        /// <para>Position is defined in _sample frames_ of decoded audio, not units of time, so that sample-perfect mixing can be achieved. To instead operate in units of time, use <see cref="CSDL.Mixer.Track.MSToFrames">MSToFrames</see> to get the approximate sample frames for a given tick.</para>
        /// <para>This function requires an input that can seek (so it can not be used if the input was set with <see cref="CSDL.Mixer.Track.SetAudioStream">SetAudioStream</see>), and a audio file format that allows seeking. SDL_mixer's decoders for some file formats do not offer seeking, or can only seek to times, not exact sample frames, in which case the final position may be off by some amount of sample frames. Please check your audio data and file bug reports if appropriate.</para>
        /// <para>It's legal to call this function on a track that is stopped, but a future call to <see cref="CSDL.Mixer.Track.Play">Play</see> will reset the start position anyhow. Paused tracks will resume at the new input position.</para>
        /// </remarks>
        /// <param name="track">the track to change.</param>
        /// <param name="frames">the sample frame position to seek to.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackPlaybackPosition">MIX_SetTrackPlaybackPosition</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.PlaybackPositionFrames">PlaybackPositionFrames</see></seealso>
        public static extern void SetTrackPlaybackPosition();

        /// <summary>
        /// <para>Set a callback that fires when a <c>MIX_Track</c> has initial decoded audio.</para>
        /// </summary>
        /// <remarks>
        /// <para>As a track needs to mix more data, it pulls from its input (a <c>MIX_Audio</c>, an SDL_AudioStream, etc). This input might be a compressed file format, like MP3, so a little more data is uncompressed from it.</para>
        /// <para>Once the track has PCM data to start operating on, it can fire a callback before _any_ changes to the raw PCM input have happened. This lets an app view the data before it has gone through transformations such as gain, 3D positioning, fading, etc. It can also change the data in any way it pleases during this callback, and the mixer will continue as if this data came directly from the input.</para>
        /// <para>Each track has its own unique raw callback.</para>
        /// <para>Passing a NULL callback here is legal; it disables this track's callback.</para>
        /// </remarks>
        /// <param name="track">the track to assign this callback to.</param>
        /// <param name="cb">the function to call when the track mixes. May be NULL.</param>
        /// <param name="userdata">an opaque pointer provided to the callback for its own personal use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackRawCallback">MIX_SetTrackRawCallback</seealso></SDLWiki>
        /// <seealso><c>MIX_TrackMixCallback</c></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetCookedCallback">SetCookedCallback</see></seealso>
        public static extern void SetTrackRawCallback();

        /// <summary>
        /// <para>Set a <c>MIX_Track</c>'s input to an SDL_IOStream providing raw PCM data.</para>
        /// </summary>
        /// <remarks>
        /// <para>This is not the recommended way to set a track's input, but this can be useful for a very specific scenario: a large file, to be played once, that must be read from disk in small chunks as needed. In most cases, however, it is preferable to create a <c>MIX_Audio</c> ahead of time and use <see cref="CSDL.Mixer.Track.SetAudio">SetAudio</see> instead.</para>
        /// <para>Also, an <see cref="CSDL.Mixer.Track.SetAudioStream">SetAudioStream</see> can _also_ provide raw PCM audio to a track, via an SDL_AudioStream, which might be preferable unless the data is already coming directly from an SDL_IOStream.</para>
        /// <para>The stream supplied here should provide an audio in raw PCM format.</para>
        /// <para>A given IOStream may only be assigned to a single track at a time; duplicate assignments won't return an error, but assigning a stream to multiple tracks will cause each track to read from the stream arbitrarily, causing confusion and incorrect mixing.</para>
        /// <para>Once a track has a valid input, it can start mixing sound by calling <see cref="CSDL.Mixer.Track.Play">Play</see>, or possibly <see cref="CSDL.Mixer.Mixer.PlayTag">PlayTag</see>.</para>
        /// <para>Calling this function with a NULL stream is legal, and removes any input from the track. If the track was currently playing, the next time the mixer runs, it'll notice this and mark the track as stopped, calling any assigned <c>MIX_TrackStoppedCallback</c>.</para>
        /// <para>It is legal to change the input of a track while it's playing, however some states, like loop points, may cease to make sense with the new audio. In such a case, one can call <see cref="CSDL.Mixer.Track.Play">Play</see> again to adjust parameters.</para>
        /// <para>The provided stream must remain valid until the track no longer needs it (either by changing the track's input or destroying the track).</para>
        /// </remarks>
        /// <param name="track">the track on which to set a new audio input.</param>
        /// <param name="io">the new i/o stream to use as the track's input.</param>
        /// <param name="spec">the format of the PCM data that the SDL_IOStream will provide.</param>
        /// <param name="closeio">if true, close the stream when done with it.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackRawIOStream">MIX_SetTrackRawIOStream</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.SetAudioStream">SetAudioStream</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.SetIOStream">SetIOStream</see></seealso>
        public static extern void SetTrackRawIOStream();

        /// <summary>
        /// <para>Force a track to stereo output, with optionally left/right panning.</para>
        /// </summary>
        /// <remarks>
        /// <para>This will cause the output of the track to convert to stereo, and then mix it only onto the Front Left and Front Right speakers, regardless of the speaker configuration. The left and right channels are modulated by <c>gains</c>, which can be used to produce panning effects. This function may be called to adjust the gains at any time.</para>
        /// <para>If <c>gains</c> is not NULL, this track will be switched into forced-stereo mode. If <c>gains</c> is NULL, this will disable spatialization (both the forced-stereo mode of this function and full 3D spatialization of <see cref="CSDL.Mixer.Track.Set3DPosition">Set3DPosition</see>).</para>
        /// <para>Negative gains are clamped to zero; there is no clamp for maximum, so one could set the value > 1.0f to make a channel louder.</para>
        /// <para>The track's 3D position, reported by <see cref="CSDL.Mixer.Track.Get3DPosition">Get3DPosition</see>, will be reset to (0, 0, 0).</para>
        /// </remarks>
        /// <param name="track">the track to adjust.</param>
        /// <param name="gains">the per-channel gains, or NULL to disable spatialization.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackStereo">MIX_SetTrackStereo</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Set3DPosition">Set3DPosition</see></seealso>
        public static extern void SetTrackStereo();

        /// <summary>
        /// <para>Set a callback that fires when a <c>MIX_Track</c> is stopped.</para>
        /// </summary>
        /// <remarks>
        /// <para>When a track completes playback, either because it ran out of data to mix (and all loops were completed as well), or it was explicitly stopped by the app, it will fire the callback specified here.</para>
        /// <para>Each track has its own unique callback.</para>
        /// <para>Passing a NULL callback here is legal; it disables this track's callback.</para>
        /// <para>Pausing a track will not fire the callback, nor will the callback fire on a playing track that is being destroyed.</para>
        /// <para>It is legal to adjust the track, including changing its input and restarting it. If this is done because it ran out of data in the middle of mixing, the mixer will start mixing the new track state in its current run without any gap in the audio.</para>
        /// </remarks>
        /// <param name="track">the track to assign this callback to.</param>
        /// <param name="cb">the function to call when the track stops. May be NULL.</param>
        /// <param name="userdata">an opaque pointer provided to the callback for its own personal use.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call SDL_GetError() for more information.</para>
        /// </returns>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_SetTrackStoppedCallback">MIX_SetTrackStoppedCallback</seealso></SDLWiki>
        /// <seealso><c>MIX_TrackStoppedCallback</c></seealso>
        public static extern void SetTrackStoppedCallback();

        /// <summary>
        /// <para>Halt all currently-playing tracks, possibly fading out over time.</para>
        /// </summary>
        /// <remarks>
        /// <para>If <c>fade_out_ms</c> is > 0, the tracks do not stop mixing immediately, but rather fades to silence over that many milliseconds before stopping. Note that this is different than <see cref="CSDL.Mixer.Track.Stop">Stop</see>, which wants sample frames; this function takes milliseconds because different tracks might have different sample rates.</para>
        /// <para>If a track ends normally while the fade-out is still in progress, the audio stops there; the fade is not adjusted to be shorter if it will last longer than the audio remaining.</para>
        /// <para>Once a track has completed any fadeout and come to a stop, it will call its <c>MIX_TrackStoppedCallback</c>, if any. It is legal to assign the track a new input and/or restart it during this callback.</para>
        /// <para>This function does not prevent new play requests from being made; it’s legal to use this function to begin fading all playing tracks but then start other tracks playing normally while those fade-outs are still in progress.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to stop all tracks.</param>
        /// <param name="fade_out_ms">the number of milliseconds to spend fading out to silence before halting. 0 to stop immediately.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_StopAllTracks">MIX_StopAllTracks</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Stop">Stop</see></seealso>
        public static extern void StopAllTracks();

        /// <summary>
        /// <para>Halt all tracks with a specific tag, possibly fading out over time.</para>
        /// </summary>
        /// <remarks>
        /// <para>If <c>fade_out_ms</c> is > 0, the tracks do not stop mixing immediately, but rather fades to silence over that many milliseconds before stopping. Note that this is different than <see cref="CSDL.Mixer.Track.Stop">Stop</see>, which wants sample frames; this function takes milliseconds because different tracks might have different sample rates.</para>
        /// <para>If a track ends normally while the fade-out is still in progress, the audio stops there; the fade is not adjusted to be shorter if it will last longer than the audio remaining.</para>
        /// <para>Once a track has completed any fadeout and come to a stop, it will call its <c>MIX_TrackStoppedCallback</c>, if any. It is legal to assign the track a new input and/or restart it during this callback. This function does not prevent new play requests from being made.</para>
        /// </remarks>
        /// <param name="mixer">the mixer on which to stop tracks.</param>
        /// <param name="tag">the tag to use when searching for tracks.</param>
        /// <param name="fade_out_ms">the number of milliseconds to spend fading out to silence before halting. 0 to stop immediately.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_StopTag">MIX_StopTag</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Stop">Stop</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.AddTag">AddTag</see></seealso>
        public static extern void StopTag();

        /// <summary>
        /// <para>Halt a currently-playing track, possibly fading out over time.</para>
        /// </summary>
        /// <remarks>
        /// <para>If <c>fade_out_frames</c> is > 0, the track does not stop mixing immediately, but rather fades to silence over that many sample frames before stopping. Sample frames are specific to the input assigned to the track, to allow for sample-perfect mixing. <see cref="CSDL.Mixer.Track.MSToFrames">MSToFrames</see> can be used to convert milliseconds to an appropriate value here.</para>
        /// <para>If the track ends normally while the fade-out is still in progress, the audio stops there; the fade is not adjusted to be shorter if it will last longer than the audio remaining.</para>
        /// <para>Once a track has completed any fadeout and come to a stop, it will call its <c>MIX_TrackStoppedCallback</c>, if any. It is legal to assign the track a new input and/or restart it during this callback.</para>
        /// <para>It is legal to halt a track that's already stopped. It does nothing, and returns true.</para>
        /// </remarks>
        /// <param name="track">the track to halt.</param>
        /// <param name="fade_out_frames">the number of sample frames to spend fading out to silence before halting. 0 to stop immediately.</param>
        /// <returns>
        /// <para>(bool) Returns true if the track has stopped, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_StopTrack">MIX_StopTrack</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Play">Play</see></seealso>
        public static extern void StopTrack();

        /// <summary>
        /// <para>Assign an arbitrary tag to a track.</para>
        /// </summary>
        /// <remarks>
        /// <para>A tag can be any valid C string in UTF-8 encoding. It can be useful to group tracks in various ways. For example, everything in-game might be marked as "game", so when the user brings up the settings menu, the app can pause all tracks involved in gameplay at once, but keep background music and menu sound effects running.</para>
        /// <para>A track can have as many tags as desired, until the machine runs out of memory.</para>
        /// <para>It's legal to add the same tag to a track more than once; the extra attempts will report success but not change anything.</para>
        /// <para>Tags can later be removed with <see cref="CSDL.Mixer.Track.RemoveTag">RemoveTag</see>.</para>
        /// </remarks>
        /// <param name="track">the track to add a tag to.</param>
        /// <param name="tag">the tag to add.</param>
        /// <returns>
        /// <para>(bool) Returns true on success, false on error; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_TagTrack">MIX_TagTrack</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.RemoveTag">RemoveTag</see></seealso>
        public static extern void TagTrack();

        /// <summary>
        /// <para>Convert sample frames for a track's current format to milliseconds.</para>
        /// </summary>
        /// <remarks>
        /// <para>This calculates time based on the track's current input format, which can change when its input does, and also if that input changes formats mid-stream (for example, if decoding a file that is two MP3s concatenated together).</para>
        /// <para>Sample frames are more precise than milliseconds, so out of necessity, this function will approximate by rounding down to the closest full millisecond.</para>
        /// <para>On various errors (<c>MIX_Init</c> was not called, the track is NULL), this returns -1. If the track has no input, this returns -1. If <c>frames</c> is &lt; 0, this returns -1.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <param name="frames">the track-specific sample frames to convert to milliseconds.</param>
        /// <returns>
        /// <para>(Sint64) Returns Converted number of milliseconds, or -1 for errors/no input; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_TrackFramesToMS">MIX_TrackFramesToMS</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.MSToFrames">MSToFrames</see></seealso>
        public static extern void TrackFramesToMS();

        /// <summary>
        /// <para>Convert milliseconds to sample frames for a track's current format.</para>
        /// </summary>
        /// <remarks>
        /// <para>This calculates time based on the track's current input format, which can change when its input does, and also if that input changes formats mid-stream (for example, if decoding a file that is two MP3s concatenated together).</para>
        /// <para>On various errors (<c>MIX_Init</c> was not called, the track is NULL), this returns -1. If the track has no input, this returns -1. If <c>ms</c> is &lt; 0, this returns -1.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <param name="ms">the milliseconds to convert to track-specific sample frames.</param>
        /// <returns>
        /// <para>(Sint64) Returns Converted number of sample frames, or -1 for errors/no input; call SDL_GetError() for details.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_TrackMSToFrames">MIX_TrackMSToFrames</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.FramesToMS">FramesToMS</see></seealso>
        public static extern void TrackMSToFrames();

        /// <summary>
        /// <para>Query if a track is currently paused.</para>
        /// </summary>
        /// <remarks>
        /// <para>If this returns true, the track is not currently contributing to the mixer's output but will when resumed (it's "paused"). It is not playing nor stopped.</para>
        /// <para>On various errors (<c>MIX_Init</c> was not called, the track is NULL), this returns false, but there is no mechanism to distinguish errors from non-playing tracks.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <returns>
        /// <para>(bool) Returns true if paused, false otherwise.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_TrackPaused">MIX_TrackPaused</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Play">Play</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Pause">Pause</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Resume">Resume</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Stop">Stop</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.IsPlaying">IsPlaying</see></seealso>
        public static extern void TrackPaused();

        /// <summary>
        /// <para>Query if a track is currently playing.</para>
        /// </summary>
        /// <remarks>
        /// <para>If this returns true, the track is currently contributing to the mixer's output (it's "playing"). It is not stopped nor paused.</para>
        /// <para>On various errors (<c>MIX_Init</c> was not called, the track is NULL), this returns false, but there is no mechanism to distinguish errors from non-playing tracks.</para>
        /// </remarks>
        /// <param name="track">the track to query.</param>
        /// <returns>
        /// <para>(bool) Returns true if playing, false otherwise.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_TrackPlaying">MIX_TrackPlaying</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.Play">Play</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Pause">Pause</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Resume">Resume</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.Stop">Stop</see></seealso>
        /// <seealso><see cref="CSDL.Mixer.Track.IsPaused">IsPaused</see></seealso>
        public static extern void TrackPlaying();

        /// <summary>
        /// <para>Unlock a mixer previously locked by a call to <see cref="CSDL.Mixer.Mixer.Lock">Lock</see>.</para>
        /// </summary>
        /// <remarks>
        /// <para>While locked, the mixer will not be able to mix more audio or change its internal state another thread. Those other threads will block until the mixer is unlocked again.</para>
        /// <para>Under the hood, this function calls SDL_LockMutex(), so all the same rules apply: the lock can be recursive, it must be unlocked the same number of times from the same thread that locked it, etc.</para>
        /// <para>Unlocking a NULL mixer is a safe no-op.</para>
        /// </remarks>
        /// <param name="mixer">the mixer to unlock. May be NULL.</param>
        /// <threadsafety>This call must be paired with a previous <see cref="CSDL.Mixer.Mixer.Lock">Lock</see> call on the same thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_UnlockMixer">MIX_UnlockMixer</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Mixer.Lock">Lock</see></seealso>
        public static extern void UnlockMixer();

        /// <summary>
        /// <para>Remove an arbitrary tag from a track.</para>
        /// </summary>
        /// <remarks>
        /// <para>A tag can be any valid C string in UTF-8 encoding. It can be useful to group tracks in various ways. For example, everything in-game might be marked as "game", so when the user brings up the settings menu, the app can pause all tracks involved in gameplay at once, but keep background music and menu sound effects running.</para>
        /// <para>It's legal to remove a tag that the track doesn't have; this function doesn't report errors, so this simply does nothing.</para>
        /// <para>Specifying a NULL tag will remove all tags on a track.</para>
        /// </remarks>
        /// <param name="track">the track from which to remove a tag.</param>
        /// <param name="tag">the tag to remove, or NULL to remove all current tags.</param>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_UntagTrack">MIX_UntagTrack</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Mixer.Track.AddTag">AddTag</see></seealso>
        public static extern void UntagTrack();

        /// <summary>
        /// <para>Get the version of SDL_mixer that is linked against your program.</para>
        /// </summary>
        /// <remarks>
        /// <para>If you are linking to SDL_mixer dynamically, then it is possible that the current version will be different than the version you compiled against. This function returns the current version, while <c>SDL_MIXER_VERSION</c> is the version you compiled with.</para>
        /// <para>This function may be called safely at any time, even before <c>MIX_Init</c>.</para>
        /// </remarks>
        /// <returns>
        /// <para>(int) Returns the version of the linked library.</para>
        /// </returns>
        /// <since>This function is available since SDL_mixer 3.0.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3_mixer/MIX_Version">MIX_Version</seealso></SDLWiki>
        /// <seealso><c>SDL_MIXER_VERSION</c></seealso>
        public static extern void Version();
    }
}
